function applyData(data, patch) {
  for (const [key, value] of Object.entries(patch)) {
    const indexed = key.match(/^(\w+)\[(\d+)\]$/)
    if (indexed) data[indexed[1]][Number(indexed[2])] = value
    else data[key] = value
  }
}

